SELECT percentile_cont(0.25) within GROUP (ORDER BY value) AS p25, percentile_cont(0.75) within GROUP (ORDER BY value) AS p75, percentile_cont(0.50) within GROUP (ORDER BY value) AS p50, (percentile_cont(0.75) within GROUP (ORDER BY value) - percentile_cont(0.25) within GROUP (ORDER BY value)) AS interquartile_range FROM labevents WHERE itemid = 84704 AND value > 100 AND subject_id IN (SELECT subject_id FROM admissions WHERE gender = 'M' AND age(CURRENT_DATE, date_trunc('year', age(CURRENT_DATE, '1970-01-01'))) BETWEEN 90 AND 100 AND chest_pain = 'yes' AND troponin_i_level > 100);